const plainText=v=>String(v??'');
const targets={
 'Anduril':{roles:'operations analysts, supply-chain analysts, programme managers and recruiters covering those teams',query:'Anduril operations supply chain UCI',topic:'production ramp-up, supplier delivery and operational bottlenecks',events:'operations panels, engineering talks and university recruiting sessions featuring Anduril speakers',sample:'a one-page supplier-delivery or capacity analysis'},
 'Harbinger':{roles:'business-systems analysts, ERP specialists, operations managers and relevant recruiters',query:'Harbinger business systems operations Garden Grove',topic:'order-to-delivery workflows, ERP integration and inventory visibility',events:'commercial-EV panels, manufacturing meetups and university sessions featuring Harbinger staff',sample:'a small order-and-inventory dashboard with one clearly explained bottleneck'},
 'Experian':{roles:'data analysts, marketing analysts, analytics managers, early-careers recruiters and UCI alumni',query:'Experian analytics UCI',topic:'customer insights, data quality and turning analysis into business decisions',events:'data and marketing talks, early-careers webinars and campus sessions featuring Experian staff',sample:'a customer-segmentation dashboard with a specific campaign recommendation'},
 'ITT Cannon':{roles:'data analysts, Power BI developers, operations leaders and recruiters supporting the Irvine team',query:'ITT Cannon data analytics Irvine',topic:'reporting automation, data quality and manufacturing dashboards',events:'manufacturing or analytics panels and university sessions involving ITT or Cannon staff',sample:'a before-and-after reporting workflow with validation checks'},
 'Rivian':{roles:'engineers or analysts in your target function, engineering managers, university recruiters and alumni',query:'Rivian Irvine intern UCI',topic:'the target team’s engineering problems, data pipelines and intern project ownership',events:'engineering talks, mobility panels and university recruiting sessions featuring Rivian speakers',sample:'a compact project demonstrating a requirement from a specific suitable vacancy'},
 'Citadel':{roles:'quantitative researchers, data scientists, campus recruiters and former competition participants',query:'Citadel datathon university recruiting',topic:'research reasoning, model validation and communicating uncertainty',events:'official datathon briefings, research talks and campus sessions, checking degree eligibility first',sample:'a reproducible analysis with clear assumptions and a short discussion of limitations'},
 'PIMCO':{roles:'investment or business analysts, client-analytics professionals, campus recruiters and UCI alumni',query:'PIMCO analyst UCI',topic:'market research, client questions and communicating investment analysis',events:'official student programmes, investment panels and university talks featuring PIMCO professionals',sample:'a one-page public-data market analysis written for a non-specialist'},
 'UCI / Habitat OC':{roles:'published event organisers, mentors, judges, alumni and professionals working on the event’s problem',query:'UCI Habitat Orange County innovation',topic:'housing workflows, useful data and practical barriers to adopting a solution',events:'the official hackathon briefing, related UCI innovation sessions and public Habitat OC events',sample:'a short housing-workflow prototype or project summary'}
};
const esc=s=>plainText(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const anonymousFace=(variant='contact')=>'<svg class="message-avatar" viewBox="0 0 64 64" role="img" aria-label="Anonymous '+(variant==='contact'?'professional':'student')+' illustration"><circle cx="32" cy="32" r="31" fill="'+(variant==='contact'?'#c7dbe5':'#d9cba8')+'"/><path d="M9 62c1-17 10-24 23-24s22 7 23 24" fill="'+(variant==='contact'?'#34546c':'#526b59')+'"/><path d="m25 40 7 12 7-12" fill="#f2f5f6"/><rect x="27" y="32" width="10" height="13" rx="4" fill="#d9ac86"/><ellipse cx="32" cy="25" rx="13" ry="16" fill="#edc6a1"/><path d="M19 25C13 6 43 2 46 20l-3 11-3-14c-7 6-14 2-19 7v8z" fill="#263747"/><circle cx="27" cy="26" r="1.4" fill="#263747"/><circle cx="37" cy="26" r="1.4" fill="#263747"/><path d="M28 33q4 3 8 0" fill="none" stroke="#966b58" stroke-width="1.5" stroke-linecap="round"/></svg>';
const linkedinLogo='<svg class="linkedin-mark" viewBox="0 0 32 32" role="img" aria-label="LinkedIn"><rect width="32" height="32" rx="5" fill="#0a66c2"/><circle cx="8" cy="9" r="2" fill="white"/><path fill="white" d="M6 13h4v13H6zm7 0h4v2c1-2 3-3 5-2 3 0 4 2 4 6v7h-4v-7c0-2-1-3-2-3-2 0-3 1-3 3v7h-4z"/></svg>';
function renderMessageDemo(company){
 const messages=[
  ['Connection request','Before connecting','Hi [Name], I’m studying [programme] at [university] and exploring [role]. Your post about [specific point] connected with my work on [project]. I’d enjoy following your perspective and connecting.'],
  ['Coffee-chat request','After they accept or reply','Thanks for connecting. I’m trying to understand [specific team problem]. Would you be open to a 15-minute coffee or video chat? I can do [time A] or [time B], or work around you. I’d value your perspective.'],
  ['Follow-up message','After your conversation','Thanks again. Your point about [specific insight] helped me rethink [project/approach]. I put together a short example showing [useful result]. Would it be helpful if I sent it over?']
 ];
 return '<div class="linkedin-demo" aria-label="Illustrative LinkedIn conversation"><div class="linkedin-demo-top">'+linkedinLogo+'<strong>Messaging</strong><span class="message-demo-label">MOCK CONVERSATION</span></div><div class="linkedin-recipient">'+anonymousFace()+'<div><strong>[Contact name]</strong><span>Professional at '+esc(company)+'</span><small>Example recipient · not a real contact</small></div><span class="contact-company-mark" aria-hidden="true">'+esc(company.split(/\s+/).map(w=>w[0]).slice(0,2).join(''))+'</span></div><div class="linkedin-messages">'+messages.map(([title,when,text])=>'<div class="message-stage"><span>'+esc(when)+'</span></div><div class="linkedin-outgoing"><div class="linkedin-message-content"><div class="message-sender">You <span>Sample · '+esc(title)+'</span></div><div class="linkedin-message-bubble"><p>'+esc(text)+'</p></div></div>'+anonymousFace('student')+'</div>').join('')+'</div><div class="linkedin-demo-composer"><span>Personalise the placeholders before sending on LinkedIn.</span><span class="demo-only-pill">Preview only</span></div></div>';
}
export function renderNetworking(company){
 const t=targets[company]||{roles:'people doing your target role, alumni and relevant early-careers recruiters',query:company+' early careers alumni',topic:'the team’s work, skills and early-career pathways',events:'official company events, university sessions and relevant professional panels',sample:'a short portfolio project related to a suitable role'};
 const steps=[
 ['Build a small target list',`Find 5–8 relevant people: ${t.roles}. Start with someone doing the work, an alumnus and a recruiter. Check their current role and team before reaching out; a senior title alone does not mean they own the vacancy.`],
 ['Find a genuine conversation starter',`Review a few recent public posts and comments about ${t.topic}. If a professional reaction or like is visible, read the original post for context, but do not assume it proves agreement or a personal interest. Save the link and one useful question. Follow the person and company to keep up with public updates.`],
 ['Connect with a specific reason',`Send a short, individual connection note referring to an actual post, shared event or relevant career path. Explain what you are exploring. If you can add a useful observation or question to a public discussion, do so before messaging; repeated generic praise is unlikely to create a meaningful conversation.`],
 ['Make the coffee chat easy to accept',`After a reply or a relevant introduction, ask for 15 minutes over coffee or video. Offer two possible times and one specific topic. Ask about the team’s problems, how strong candidates demonstrate fit and where your preparation could improve. Make clear that you are seeking their perspective, not expecting them to arrange a job.`],
 ['Use events as a reason to meet',`Check weekly for ${t.events}. Confirm the speaker and registration on the organiser’s page. Prepare one question tied to their published work, introduce yourself briefly and follow up with the point you discussed. A company logo or an employee’s attendance is not proof that an event is recruiting.`],
 ['Follow up with something useful',`Within a day or two of a conversation, send a concise thank-you and one relevant takeaway. If useful, offer ${t.sample}, using public or synthetic data. Ask permission before sending a large attachment. Show how you applied their advice rather than asking repeatedly whether they have a vacancy.`],
 ['Ask for a next step when there is a fit',`If a suitable live role emerges and the person has seen your work, share the job link and ask whether they think your background fits. If appropriate, ask whether they would feel comfortable introducing you or referring you. Apply before the deadline regardless of whether a referral arrives. For an unanswered message, send one brief follow-up after roughly a week, then leave space.`]
 ];
 return '<div class="networking-plan"><h5>Build relationships around the role</h5><p class="muted">Suggested approach for '+esc(company)+'. These are people and events to look for, not verified contacts or confirmed upcoming events.</p><ol class="networking-steps">'+steps.map(([h,p],i)=>'<li><details class="networking-step" name="networking-step"><summary><span class="networking-number">'+(i+1)+'</span><span>'+esc(h)+'</span></summary><div class="networking-step-body"><p>'+esc(p)+'</p></div></details></li>').join('')+'</ol><a class="networking-search" href="https://www.linkedin.com/search/results/people/?keywords='+encodeURIComponent(t.query)+'" target="_blank" rel="noopener noreferrer">Search LinkedIn for relevant people ↗</a>'+
 '<details class="outreach-examples"><summary>Example messages and a simple weekly routine</summary>'+renderMessageDemo(company)+'<p><strong>Weekly routine:</strong> Review your target list and event announcements, send two or three well-researched messages, and follow up where appropriate. Track the source link, conversation topic, last contact, agreed next step and application deadline. Judge progress by useful conversations and clearer role fit, not connection counts.</p><p>Use only details you actually read or discussed. Personalise these examples to your own background. Public professional activity is useful context, not evidence of someone’s private preferences or willingness to refer you.</p><p class="muted">Guidance: <a href="https://career.uci.edu/undergraduate/informational-interviews/" target="_blank" rel="noopener noreferrer">UCI informational interviews</a> · <a href="https://www.linkedin.com/help/linkedin/answer/a595755" target="_blank" rel="noopener noreferrer">LinkedIn following and visibility</a>. The suggested cadence is a practical starting point, not a tested formula for higher offer rates.</p></details></div>';
}
